// ===============================================================================
// DAEMIND SRE - PARSER DETALHADO DA LOJA INTEGRADA (ITENS, FRETE, CUPOM, CMV)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

// 1. Extração e sanitização do cliente
const cliente = body.cliente || {};
let rawPhone = (cliente.telefone_celular || cliente.telefone_principal || body.telefone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (cliente.nome || 'Cliente Loja Integrada').trim();
const clienteEmail = (cliente.email || '').trim().toLowerCase();
const clienteCpf = (cliente.cpf || cliente.cnpj || '').toString().replace(/\D/g, '');

// 2. Extração de valores e totais
const numeroPedido = parseInt(body.numero || body.id || Date.now(), 10);
const valorTotal = parseFloat(body.valor_total || 0);
const valorFrete = parseFloat(body.valor_frete || body.envios?.[0]?.valor || 0);
const valorDesconto = parseFloat(body.valor_desconto || 0);
const cupomAplicado = body.cupom?.codigo || body.cupom_desconto || '';
const formaPagamento = body.pagamentos?.[0]?.forma_pagamento?.nome || 'PIX/Cartão';
const formaEnvio = body.envios?.[0]?.forma_envio?.nome || 'Correios/Transportadora';

// 3. Mapeamento estrito de status
const situacaoCodigo = body.situacao?.codigo || body.situacao?.nome || 'pedido_criado';
let statusOperacional = 'Pendente';
if (['pedido_pago', 'pago', 'aprovado'].includes(situacaoCodigo)) {
  statusOperacional = 'Pago';
} else if (['aguardando_pagamento', 'pedido_criado'].includes(situacaoCodigo)) {
  statusOperacional = formaPagamento.toLowerCase().includes('boleto') ? 'Pendente_Boleto' : 'Pendente_PIX';
} else if (['pedido_enviado', 'enviado'].includes(situacaoCodigo)) {
  statusOperacional = 'Enviado';
} else if (['pedido_cancelado', 'cancelado'].includes(situacaoCodigo)) {
  statusOperacional = 'Cancelado';
}

// 4. Parsing detalhado dos itens do pedido
const rawItens = body.itens || [];
const itensNormalizados = rawItens.map(i => ({
  produto_nome: i.nome || i.produto_nome || 'Produto',
  sku: i.sku || 'SKU_PADRAO',
  quantidade: parseInt(i.quantidade || 1, 10),
  preco_venda: parseFloat(i.preco_venda || i.valor_venda || 0),
  preco_custo: parseFloat(i.preco_custo || (parseFloat(i.preco_venda || 0) * 0.5))
}));

const dedupHash = crypto.createHash('sha256').update(`lojaintegrada_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_cpf: clienteCpf,
    valor_total: valorTotal,
    valor_frete: valorFrete,
    valor_desconto: valorDesconto,
    cupom_aplicado: cupomAplicado,
    forma_pagamento: formaPagamento,
    forma_envio: formaEnvio,
    status_operacional: statusOperacional,
    itens: itensNormalizados
  }
}];
